import{_ as d,o as a,c as r,a2 as h}from"./chunks/framework.CqpfiAoK.js";const u=JSON.parse('{"title":"الشخصيات الرئيسية والمنظمات","description":"","frontmatter":{},"headers":[],"relativePath":"ar/0095-关键人物与组织.md","filePath":"ar/0095-关键人物与组织.md"}'),e={name:"ar/0095-关键人物与组织.md"};function n(o,t,l,i,b,s){return a(),r("div",null,[...t[0]||(t[0]=[h('<h1 id="الشخصيات-الرئيسية-والمنظمات" tabindex="-1">الشخصيات الرئيسية والمنظمات <a class="header-anchor" href="#الشخصيات-الرئيسية-والمنظمات" aria-label="Permalink to &quot;الشخصيات الرئيسية والمنظمات&quot;">​</a></h1><table tabindex="0"><thead><tr><th>العنصر</th><th>المحتوى</th></tr></thead><tbody><tr><td>رقم الوثيقة</td><td>95</td></tr><tr><td>الوحدة</td><td>الملاحق والمواد المرجعية</td></tr><tr><td>الكلمات المفتاحية</td><td>الشخصيات الرئيسية، المنظمات المهمة، الأدوار التاريخية، الوظائف المؤسسية، الحضارة التكافلية</td></tr></tbody></table><h2 id="أولاً-ملاحظات" tabindex="-1">أولاً: ملاحظات <a class="header-anchor" href="#أولاً-ملاحظات" aria-label="Permalink to &quot;أولاً: ملاحظات&quot;">​</a></h2><p>تضم هذه الوثيقة الشخصيات الرئيسية والمنظمات المهمة في مسيرة تطور حضارة التكافل المرساة، مرتبة حسب الحقب التاريخية وأنواع المنظمات. يذكر قسم الشخصيات الرئيسية لكل شخصية اسمها وعصرها وإسهاماتها الجوهرية ومكانتها التاريخية؛ ويذكر قسم المنظمات المهمة لكل منظمة اسمها وتاريخ تأسيسها ووظائفها الجوهرية ودورها التاريخي. هذه الوثيقة محدثة باستمرار؛ فمع تقدم التاريخ وتطور المنظمات ستُستكمل وتُنقح تباعاً.</p><h2 id="ثانياً-الشخصيات-الرئيسية" tabindex="-1">ثانياً: الشخصيات الرئيسية <a class="header-anchor" href="#ثانياً-الشخصيات-الرئيسية" aria-label="Permalink to &quot;ثانياً: الشخصيات الرئيسية&quot;">​</a></h2><h3 id="_2-1-رواد-الفكر-في-عصر-ما-قبل-المرساة" tabindex="-1">2.1 رواد الفكر في عصر ما قبل المرساة <a class="header-anchor" href="#_2-1-رواد-الفكر-في-عصر-ما-قبل-المرساة" aria-label="Permalink to &quot;2.1 رواد الفكر في عصر ما قبل المرساة&quot;">​</a></h3><table tabindex="0"><thead><tr><th>الاسم</th><th>العصر</th><th>الإسهامات الجوهرية</th><th>المكانة التاريخية</th></tr></thead><tbody><tr><td>Xuánhéng Zǐ</td><td>نحو −500 مليون سنة</td><td>أول مفكر راجع نظام الزراعة الافتراسية مراجعة منهجية؛ طرح النموذج الأولي لمفهوم «التكافل»؛ مؤلف الجزء الباقي من Fǎn Lüèduó Lùn (رسالة ضد الافتراس)</td><td>الرائد القديم للفكر التكافلي؛ صار فكره، بعد نوم مئات الملايين من السنين، المنبع الروحي لحضارة التكافل المرساة</td></tr><tr><td>Wànlíng Mǔ</td><td>نحو −100 مليون سنة</td><td>قادت أول حضارة تجريبية تكافلية واسعة النطاق؛ ورغم أن الحضارات الافتراسية دمرتها في النهاية، أثبتت ممارستها جدوى النظام التكافلي</td><td>رائدة الممارسة التكافلية، أطلق عليها الأجيال اللاحقة لقب «أم التكافل»</td></tr><tr><td>Máo Jué Zhě</td><td>نحو −10,000 سنة</td><td>مزارع من البعد الأول، أدرك أثناء زراعة طويلة عقدة مستقرة في شبكة القوانين بالصدفة واكتشف آلية المرساة</td><td>مكتشف آلية المرساة وبادئ عصر صحوة المرساة</td></tr></tbody></table><h3 id="_2-2-مؤسسو-عصر-صحوة-المرساة" tabindex="-1">2.2 مؤسسو عصر صحوة المرساة <a class="header-anchor" href="#_2-2-مؤسسو-عصر-صحوة-المرساة" aria-label="Permalink to &quot;2.2 مؤسسو عصر صحوة المرساة&quot;">​</a></h3><table tabindex="0"><thead><tr><th>الاسم</th><th>العصر</th><th>الإسهامات الجوهرية</th><th>المكانة التاريخية</th></tr></thead><tbody><tr><td>Máo Dìng Gōng</td><td>−10,000 إلى −9200 سنة</td><td>تلميذ Máo Jué Zhě؛ درس آلية المرساة دراسة منهجية؛ أنشأ أول مرساة اصطناعية؛ مؤلف Máodiǎn Yuánlǐ (مبادئ المرساة)</td><td>مؤسس تقنية المرساة ومخترع المرساة الاصطناعية</td></tr><tr><td>Gòngshēng Zǐ</td><td>−6000 إلى −5100 سنة</td><td>جمع بين تقنية المرساة والفكر التكافلي؛ أسس المنظومة النظرية لـ«تكافل المرساة»؛ مؤلف Máodiǎn Gòngshēng Lùn (في تكافل المرساة)</td><td>مؤسس نظرية تكافل المرساة والمرشد الفكري للحضارة التكافلية</td></tr><tr><td>Héngyuán Gōng</td><td>−5000 إلى −4300 سنة</td><td>أسس أول دولة-مدينة تكافلية قائمة على المرساة «Héngyuan Chéng»، وصد بنجاح هجمات الحضارات الافتراسية</td><td>مؤسس أول دولة-مدينة تكافلية وممارس للنظام التكافلي</td></tr><tr><td>Wànzú Shǐ</td><td>−2000 إلى −1200 سنة</td><td>أطلق أول «الجمعية الكبرى لتكافل عشرة آلاف عرق»؛ جاب عشرات الأعراق داعياً إلى الاتحاد التكافلي</td><td>مناصر اتحاد عشرة آلاف عرق ورائد التكافل بين الأعراق</td></tr></tbody></table><h3 id="_2-3-مؤسسو-الدولة-في-فترة-تأسيس-النظام-التكافلي" tabindex="-1">2.3 مؤسسو الدولة في فترة تأسيس النظام التكافلي <a class="header-anchor" href="#_2-3-مؤسسو-الدولة-في-فترة-تأسيس-النظام-التكافلي" aria-label="Permalink to &quot;2.3 مؤسسو الدولة في فترة تأسيس النظام التكافلي&quot;">​</a></h3><table tabindex="0"><thead><tr><th>الاسم</th><th>العصر</th><th>الإسهامات الجوهرية</th><th>المكانة التاريخية</th></tr></thead><tbody><tr><td>Lìxiàn Gōng</td><td>−1000 إلى −900 سنة</td><td>رئيس لجنة صياغة الدستور التكافلي؛ ترأس صياغة الدستور التكافلي وأجازه بالاستفتاء الشعبي</td><td>المعد الرئيسي للدستور التكافلي والأب المؤسس للدستورية في الحضارة التكافلية</td></tr><tr><td>Zhífǎ Gōng</td><td>−900 إلى −780 سنة</td><td>أول رئيس للجنة التنفيذية التكافلية؛ ترأس إنشاء النظام الإداري وآليات إنفاذ القانون في الحضارة التكافلية</td><td>مؤسس النظام الإداري التكافلي وأول رئيس للإدارة</td></tr><tr><td>Sīfǎ Mǔ</td><td>−900 إلى −800 سنة</td><td>أول رئيسة قضاة في محكمة التكافل؛ أسست النظام القضائي ونظام المراجعة الدستورية للحضارة التكافلية</td><td>مؤسسة النظام القضائي التكافلي وأول رئيسة للسلطة القضائية</td></tr><tr><td>Sānbǎi Shī</td><td>−500 إلى −300 سنة</td><td>ترأس أعمال التنقيب وتنظيم أنظمة الزراعة الأصلانية الثلاثمائة؛ قاد الفريق لإكمال التحقق من الأنظمة الثلاثمائة كلها</td><td>المعد الرئيسي للأنظمة الثلاثمائة والقائد العام لهندسة فتح الزراعة</td></tr><tr><td>Bèizēng Gōng</td><td>−300 إلى −220 سنة</td><td>ترأس أبحاث التطبيق التقني لثمرة المضاعفة؛ حقق الاختراق الهندسي لتقنية التعزيز الاستنتاجي مئة ضعف</td><td>كبير علماء تقنية ثمرة المضاعفة ومحرك نظام الاستنتاج التكراري</td></tr></tbody></table><h3 id="_2-4-قادة-فترة-الفتح-والتنشيط" tabindex="-1">2.4 قادة فترة الفتح والتنشيط <a class="header-anchor" href="#_2-4-قادة-فترة-الفتح-والتنشيط" aria-label="Permalink to &quot;2.4 قادة فترة الفتح والتنشيط&quot;">​</a></h3><table tabindex="0"><thead><tr><th>الاسم</th><th>العصر</th><th>الإسهامات الجوهرية</th><th>المكانة التاريخية</th></tr></thead><tbody><tr><td>Kāifàng Gōng</td><td>−100 إلى −50 سنة</td><td>ترأس الفتح الكامل لأنظمة الزراعة الأصلانية الثلاثمائة؛ أنشأ نظام توزيع موارد الزراعة وشبكة الإرشاد</td><td>القائد العام لفتح الأنظمة الثلاثمائة وممارس مبدأ «طريق لكل فرد»</td></tr><tr><td>Jīhuó Gōng</td><td>−50 سنة إلى السنة الأولى</td><td>ترأس تنفيذ استراتيجية التنشيط بنسبة 20٪؛ قاد الفريق لإنجاز هدف تنشيط 20٪ من الكائنات خلال 50 سنة</td><td>القائد العام لاستراتيجية التنشيط بنسبة 20٪ وبادئ العصر الجديد للحضارة التكافلية</td></tr><tr><td>Shēngwéi Gōng</td><td>السنة الأولى إلى 80</td><td>ترأس مشروع الارتقاء الأول؛ دفع تنفيذ مسار الارتقاء بأربع مراحل؛ حقق أول ارتقاء مرحلي</td><td>المهندس الرئيسي للارتقاء الأول وقائد عصر الارتقاء</td></tr></tbody></table><h3 id="_2-5-مستكشفو-عصر-جمهورية-عشرة-آلاف-عرق-والعصر-عبر-الأبعاد" tabindex="-1">2.5 مستكشفو عصر جمهورية عشرة آلاف عرق والعصر عبر الأبعاد <a class="header-anchor" href="#_2-5-مستكشفو-عصر-جمهورية-عشرة-آلاف-عرق-والعصر-عبر-الأبعاد" aria-label="Permalink to &quot;2.5 مستكشفو عصر جمهورية عشرة آلاف عرق والعصر عبر الأبعاد&quot;">​</a></h3><table tabindex="0"><thead><tr><th>الاسم</th><th>العصر</th><th>الإسهامات الجوهرية</th><th>المكانة التاريخية</th></tr></thead><tbody><tr><td>Wànzú Gòngzhǔ</td><td>100 إلى 200</td><td>ترأس تأسيس جمهورية عشرة آلاف عرق؛ دفع تدوين سجل عشرة آلاف عرق وسياسات الاندماج بين الأعراق</td><td>مؤسس جمهورية عشرة آلاف عرق وأول حاكم أعلى لعشرة آلاف عرق</td></tr><tr><td>Wèimiàn Mǔ</td><td>500 إلى 650</td><td>أول مديرة لإدارة الأبعاد؛ ترأست برنامج الاستكشاف عبر الأبعاد واسع النطاق؛ أنشأت القاعدة الرئيسية لإحداثيات الأبعاد</td><td>رائدة الاستكشاف عبر الأبعاد ومؤسسة نظام إدارة الأبعاد</td></tr><tr><td>Kǎogǔ Gōng</td><td>800 إلى 950</td><td>ترأس النضج النهائي لمخطط الآثار عن بُعد بمرآة النسخ؛ أدخل الآثار عبر الأبعاد عصر النطاق الواسع</td><td>ذروة المخططات الأثرية ومؤسس الآثار عبر الأبعاد</td></tr><tr><td>Shílǜ Gōng</td><td>1000 إلى 1150</td><td>ترأس اختراق تقنية الارتداد الزمني؛ دفع إرساء مبدأ الملاحظة أولاً ثم التدخل المحدود</td><td>قائد تقنية الارتداد الزمني وواضع مبادئ قوانين الزمن</td></tr></tbody></table><h2 id="ثالثاً-المنظمات-المهمة" tabindex="-1">ثالثاً: المنظمات المهمة <a class="header-anchor" href="#ثالثاً-المنظمات-المهمة" aria-label="Permalink to &quot;ثالثاً: المنظمات المهمة&quot;">​</a></h2><h3 id="_3-1-مؤسسات-السلطة-العليا" tabindex="-1">3.1 مؤسسات السلطة العليا <a class="header-anchor" href="#_3-1-مؤسسات-السلطة-العليا" aria-label="Permalink to &quot;3.1 مؤسسات السلطة العليا&quot;">​</a></h3><table tabindex="0"><thead><tr><th>المنظمة</th><th>تاريخ التأسيس</th><th>الوظائف الجوهرية</th><th>الدور التاريخي</th></tr></thead><tbody><tr><td>المجلس التشريعي للمرساة</td><td>−900 سنة</td><td>أعلى مؤسسة سلطة في الحضارة التكافلية، تتكون من ممثلين عن جميع الأعراق بنسب متوازنة، تمارس السلطة التشريعية وسلطة البت في الأمور الكبرى</td><td>أعلى مؤسسة للبت في الحضارة التكافلية وواضعة جميع القوانين والاستراتيجيات الكبرى</td></tr><tr><td>اللجنة التنفيذية التكافلية</td><td>−900 سنة</td><td>أعلى مؤسسة إدارية في الحضارة التكافلية، مسؤولة عن تنفيذ الدستور والقوانين والحكم اليومي</td><td>أعلى جهاز إداري في الحضارة التكافلية ومنفذة القوانين والسياسات</td></tr><tr><td>محكمة التكافل</td><td>−900 سنة</td><td>أعلى مؤسسة قضائية في الحضارة التكافلية، تمارس السلطة القضائية باستقلال، مسؤولة عن المراجعة الدستورية والفصل في القضايا الكبرى</td><td>أعلى جهاز قضائي في الحضارة التكافلية وحارسة حكم القانون</td></tr><tr><td>لجنة الرقابة للمرساة</td><td>−900 سنة</td><td>مؤسسة رقابية مستقلة، مسؤولة عن الإشراف على جميع مؤسسات السلطة لمنع إساءة استخدام السلطة</td><td>الجهاز الرقابي المستقل للحضارة التكافلية وحلقة مفتاحية في توازن السلطات</td></tr></tbody></table><h3 id="_3-2-مؤسسات-الإدارة-المتخصصة" tabindex="-1">3.2 مؤسسات الإدارة المتخصصة <a class="header-anchor" href="#_3-2-مؤسسات-الإدارة-المتخصصة" aria-label="Permalink to &quot;3.2 مؤسسات الإدارة المتخصصة&quot;">​</a></h3><table tabindex="0"><thead><tr><th>المنظمة</th><th>تاريخ التأسيس</th><th>الوظائف الجوهرية</th><th>الدور التاريخي</th></tr></thead><tbody><tr><td>إدارة الأبعاد</td><td>500</td><td>مسؤولة عن صيانة القاعدة الرئيسية لإحداثيات الأبعاد، وإصدار تصاريح التنقل، وإدارة الآثار عبر الأبعاد، والتنسيق الدبلوماسي عبر الأبعاد</td><td>السلطة المختصة للتفاعل عبر الأبعاد ومدير استكشاف الأبعاد</td></tr><tr><td>لجنة قوانين الزمن</td><td>1000</td><td>مسؤولة عن الموافقة على عمليات الارتداد الزمني، وبحوث قوانين الزمن، والإشراف على منع المفارقات الزمنية والسيطرة عليها</td><td>مؤسسة الموافقة والإشراف على عمليات الارتداد الزمني وحارسة سلامة قوانين الزمن</td></tr><tr><td>لجنة تدقيق قوانين الزمن</td><td>1050</td><td>مسؤولة عن التدقيق اللاحق لعمليات الارتداد الزمني، والتأكد من عدم حدوث اضطراب غير مسيطر عليه في الخط الزمني</td><td>المؤسسة المستقلة لتدقيق العمليات الزمنية وآخر خط دفاع لسلامة الارتداد الزمني</td></tr><tr><td>لجنة الأخلاق عبر الأبعاد</td><td>600</td><td>تضع وتفسر المبادئ الأخلاقية عبر الأبعاد، وتوافق على مشاريع التفاعل عبر الأبعاد عالية الخطورة، وتعالج شكاوى انتهاكات الأخلاقيات</td><td>مؤسسة الإشراف الأخلاقي على التفاعل عبر الأبعاد وحارسة ذاتية الحضارات</td></tr><tr><td>مكتب تدقيق إعادة المعرفة</td><td>850</td><td>مسؤول عن تدقيق عمليات إعادة المعرفة، وضمان مطابقة المحتوى المعاد لمبدأ «إعادة المعرفة فقط»</td><td>مؤسسة تدقيق إعادة المعرفة وحلقة مفتاحية في منع التلوث عبر الأبعاد</td></tr></tbody></table><h3 id="_3-3-مؤسسات-البحث-والتعليم" tabindex="-1">3.3 مؤسسات البحث والتعليم <a class="header-anchor" href="#_3-3-مؤسسات-البحث-والتعليم" aria-label="Permalink to &quot;3.3 مؤسسات البحث والتعليم&quot;">​</a></h3><table tabindex="0"><thead><tr><th>المنظمة</th><th>تاريخ التأسيس</th><th>الوظائف الجوهرية</th><th>الدور التاريخي</th></tr></thead><tbody><tr><td>معهد أبحاث المرساة</td><td>−8000 سنة</td><td>البحث الأساسي والتطوير التطبيقي لآلية المرساة؛ بناء وصيانة المراسي الاصطناعية</td><td>مؤسسة البحث الجوهرية لتقنية المرساة وأحد المصادر التقنية للحضارة التكافلية</td></tr><tr><td>لجنة تنظيم الأنظمة الثلاثمائة</td><td>−500 سنة</td><td>تنقيب وتنظيم وتحقق وتحسين مستمر لأنظمة الزراعة الأصلانية الثلاثمائة</td><td>مؤسسة تنظيم وصيانة الأنظمة الثلاثمائة والسند التقني لفتح الزراعة</td></tr><tr><td>تحالف الجامعات التكافلي</td><td>−700 سنة</td><td>اتحاد للتعليم العالي وتعليم الزراعة، مسؤول عن إعداد الكفاءات العليا والبحث الأكاديمي</td><td>تحالف أعلى مؤسسات التعليم في الحضارة التكافلية ونواة إعداد الكفاءات والابتكار الأكاديمي</td></tr><tr><td>أكاديمية الآثار عبر الأبعاد</td><td>550</td><td>تُعد الكفاءات المتخصصة في الآثار عبر الأبعاد؛ وتجري أبحاث التقنيات الأثرية وابتكارات المناهج</td><td>مركز إعداد الكفاءات والبحث والتطوير التقني للآثار عبر الأبعاد</td></tr><tr><td>معهد أبحاث قوانين الزمن</td><td>950</td><td>البحث النظري الأساسي لقوانين الزمن وتطوير تقنية الارتداد الزمني</td><td>المؤسسة الجوهرية لبحوث قوانين الزمن ومهد تقنية الارتداد الزمني</td></tr></tbody></table><h3 id="_3-4-المنظمات-العسكرية-والأمنية" tabindex="-1">3.4 المنظمات العسكرية والأمنية <a class="header-anchor" href="#_3-4-المنظمات-العسكرية-والأمنية" aria-label="Permalink to &quot;3.4 المنظمات العسكرية والأمنية&quot;">​</a></h3><table tabindex="0"><thead><tr><th>المنظمة</th><th>تاريخ التأسيس</th><th>الوظائف الجوهرية</th><th>الدور التاريخي</th></tr></thead><tbody><tr><td>قوات الدفاع التكافلية</td><td>−850 سنة</td><td>قوة الدفاع النظامية للحضارة التكافلية، مسؤولة عن الدفاع عن الأبعاد والتصدي للتهديدات الخارجية</td><td>القوة العسكرية الرئيسية للحضارة التكافلية ومدافعة الأمن الوطني</td></tr><tr><td>فيلق دوريات الأبعاد</td><td>520</td><td>مسؤول عن دوريات الأبعاد المستكشفة والمراقبة الأمنية والتصدي للأحداث الأمنية عبر الأبعاد</td><td>قوة الخط الأول للأمن عبر الأبعاد وحافظ نظام الأبعاد</td></tr><tr><td>فريق الاستجابة الطارئة لتلوث القوانين</td><td>600</td><td>مسؤول عن الاستجابة الطارئة لأحداث تلوث القوانين وتلوث الطاقة وإزالة التلوث</td><td>قوة المعالجة الطارئة لتلوث القوانين وحارس البيئة الكونية</td></tr><tr><td>وحدة الاستجابة الطارئة للمفارقات الزمنية</td><td>1020</td><td>مسؤولة عن الاستجابة الطارئة لأحداث المفارقات الزمنية وعمليات إصلاح السببية</td><td>قوة المعالجة الطارئة للمفارقات الزمنية والضمانة الأخيرة لاستقرار الخط الزمني</td></tr></tbody></table><h3 id="_3-5-المنظمات-المدنية-والاجتماعية" tabindex="-1">3.5 المنظمات المدنية والاجتماعية <a class="header-anchor" href="#_3-5-المنظمات-المدنية-والاجتماعية" aria-label="Permalink to &quot;3.5 المنظمات المدنية والاجتماعية&quot;">​</a></h3><table tabindex="0"><thead><tr><th>المنظمة</th><th>تاريخ التأسيس</th><th>الوظائف الجوهرية</th><th>الدور التاريخي</th></tr></thead><tbody><tr><td>الجمعية الكبرى لتكافل عشرة آلاف عرق</td><td>−2000 سنة</td><td>اجتماعات دورية لممثلي جميع الأعراق، تناقش شؤون التكافل بين الأعراق وتعزز التبادل الثقافي</td><td>منصة مهمة للتبادل بين جميع الأعراق والمنظمة السابقة لجمهورية عشرة آلاف عرق</td></tr><tr><td>جمعية المزارعين</td><td>−600 سنة</td><td>المنظمة الذاتية لقطاع الزراعة، مسؤولة عن حماية حقوق المزارعين ووضع المعايير القطاعية</td><td>المنظمة الذاتية للمزارعين ومحرك معايير قطاع الزراعة</td></tr><tr><td>جمعية المستهلكين</td><td>−650 سنة</td><td>منظمة حماية حقوق المستهلك، مسؤولة عن الدفاع عن حقوق المستهلك وتثقيف المستهلك والرقابة المجتمعية</td><td>لسان حقوق المستهلك والمشرف المجتمعي على نظام السوق</td></tr><tr><td>تحالف حماية البيئة</td><td>−550 سنة</td><td>منظمة مدنية موحدة لحماية البيئة، مسؤولة عن الرقابة البيئية والتثقيف البيئي وأنشطة التطوع لاستعادة النظم البيئية</td><td>القوة الاجتماعية لحماية البيئة ومحرك الحضارة الإيكولوجية الكونية</td></tr><tr><td>جمعية الصداقة عبر الأبعاد</td><td>580</td><td>منظمة مدنية تعزز التبادل الودي بين حضارات الأبعاد، مسؤولة عن الدبلوماسية الشعبية والتبادل الثقافي</td><td>القوة الجوهرية للدبلوماسية الشعبية عبر الأبعاد وجسر التفاهم بين الحضارات</td></tr></tbody></table><h2 id="الخلاصة" tabindex="-1">الخلاصة <a class="header-anchor" href="#الخلاصة" aria-label="Permalink to &quot;الخلاصة&quot;">​</a></h2><p>الشخصيات الرئيسية والمنظمات هي الحامل الحي لتاريخ حضارة التكافل المرساة. من رواد الفكر القدماء إلى قادة الحضارة المعاصرين، ومن مؤسسات السلطة العليا إلى المنظمات الاجتماعية المدنية، يؤدي كل شخصية وكل منظمة دوراً لا يُعوَّض في السردية الكبرى للحضارة التكافلية. كفاحهم وإسهاماتهم ينسجون معاً الملحمة العظيمة لحضارة التكافل المرساة — من العدم إلى الوجود، ومن الصغر إلى الكبر، ومن بُعدها الخاص إلى الكون كله.</p><h2 id="الوثائق-ذات-الصلة" tabindex="-1">الوثائق ذات الصلة <a class="header-anchor" href="#الوثائق-ذات-الصلة" aria-label="Permalink to &quot;الوثائق ذات الصلة&quot;">​</a></h2><ul><li>70-纪元划分总表 (الجدول الرئيسي لتقسيم العصور)</li><li>49-治理框架与权力制衡 (إطار الحوكمة وتوازن السلطات)</li><li>77-万族共和成立 (تأسيس جمهورية عشرة آلاف عرق)</li></ul>',30)])])}const c=d(e,[["render",n]]);export{u as __pageData,c as default};
